foreach(string n in new[]{"HealthTrack","FoodTrack"}){var track=hud.Find("Vitals/"+n);C<UnityEngine.UI.Image>(track.Find("Fill")).color=n=="HealthTrack"?new Color(.75f,.82f,.72f):new Color(.78f,.75f,.88f);}
